package com.cpf.starter.ftps;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;@AutoConfiguration @EnableConfigurationProperties(CpfFtpsProperties.class) @ConditionalOnProperty(prefix="cpf.integration.ftps",name="enabled",havingValue="true") public class CpfFtpsAutoConfiguration {@Bean CpfFtpsClient cpfFtpsClient(CpfFtpsProperties p){p.validate();return new CpfFtpsClient(p);}}
